∀ {ℒ : Type u_1} [inst : Nontrivial ℒ] [inst_1 : Lattice ℒ] [inst_2 : BoundedOrder ℒ] {S : Type u_2}
  [inst_3 : CompleteLattice S] {μ : { p // p.1 < p.2 } → S},
  (∀ (a b : ℒ) (h : ¬a ≤ b), μ ⟨(a ⊓ b, a), ⋯⟩ = μ ⟨(b, a ⊔ b), ⋯⟩) → HarderNarasimhan.Affine μ

∀ {ℒ : Type u_1} [inst : Nontrivial ℒ] [inst_1 : Lattice ℒ] [inst_2 : BoundedOrder ℒ] [WellFoundedGT ℒ] {S : Type u_2}
  [inst_4 : CompleteLinearOrder S] (μ : { p // p.1 < p.2 } → S) [HarderNarasimhan.SlopeLike μ] (I : { p // p.1 < p.2 }),
  HarderNarasimhan.μmin μ I = HarderNarasimhan.μA μ I

∀ {ℒ : Type u_1} [inst : Nontrivial ℒ] [inst_1 : Lattice ℒ] [inst_2 : BoundedOrder ℒ] {S : Type u_2}
  [inst_3 : CompleteLinearOrder S] (μ : { p // p.1 < p.2 } → S),
  HarderNarasimhan.Semistable μ → HarderNarasimhan.μBstar μ ≤ HarderNarasimhan.μAstar μ

