  HarderNarasimhan.Semistable μ ↔ HarderNarasimhan.semistableI μ HarderNarasimhan.TotIntvl

∀ {ℒ : Type u_1} {inst : Nontrivial ℒ} {inst_1 : PartialOrder ℒ} {inst_2 : BoundedOrder ℒ} {S : Type u_2}
