  HarderNarasimhan.μAstar μ = HarderNarasimhan.μBstar μ

∀ {ℒ : Type u_1} {inst : Nontrivial ℒ} {inst_1 : PartialOrder ℒ} {inst_2 : BoundedOrder ℒ} {S : Type u_2}
  {inst_3 : CompleteLattice S} {μ : { p // p.1 < p.2 } → S} [self : HarderNarasimhan.WeakAscendingChainCondition μ]
  (x : ℕ → ℒ) (smf : StrictMono x), ∃ N, μ ⟨(x N, x (N + 1)), ⋯⟩ ≤ μ ⟨(x N, ⊤), ⋯⟩

